// =====================================================================
//  PARAMÈTRES DE LA VEILLE QUOTIDIENNE : c'est le seul nœud à modifier.
// =====================================================================

// 1) Où envoyer l'alerte et où ranger les signaux
const email = 'ton.email@exemple.com';
const googleSheetUrl = 'https://docs.google.com/spreadsheets/d/COLLE_ICI_L_ID_DE_TA_FEUILLE/edit';

// 2) Mots-clés produits, en français ET en anglais. Un signal n'est gardé que s'il en contient au moins un.
//    Écris-les en minuscules, avec les accents. « bean » trouve aussi « beans », « fertili » trouve « fertilizer ».
const motsCles = [
  'maïs', 'maize', 'riz', 'rice', 'manioc', 'cassava', 'gari', 'tapioca', 'cacao', 'cocoa', 'café', 'coffee',
  'poivre', 'pepper', 'piment', 'chili', 'gingembre', 'ginger', 'sésame', 'sesame', 'soja', 'soybean', 'soya',
  'arachide', 'groundnut', 'peanut', 'oignon', 'onion', 'pomme de terre', 'pommes de terre', 'potato', 'haricot',
  'niébé', 'cowpea', 'sorgho', 'sorghum', 'millet', 'huile de palme', 'palm oil', 'banane', 'banana',
  'plantain', 'ananas', 'pineapple', 'avocado', 'mangue', 'mango', 'cajou', 'cashew', 'karité', 'shea',
  'noix de cola', 'kola', 'volaille', 'poulet', 'poultry', 'chicken', 'œuf', 'oeuf', 'egg', 'poisson', 'fish',
  'semence', 'seed', 'engrais', 'fertili', 'provende', 'aliment pour bétail', 'animal feed', 'farine', 'flour',
  'céréale', 'cereal', 'grain', 'vivres', 'denrée', 'foodstuff', 'food supply', 'sucre', 'sugar',
];

// 3) Mots qui rendent un signal urgent (pénurie, interdiction, flambée des prix…)
const motsAlerte = [
  'pénurie', 'shortage', 'flambée', 'envolée', 'surge', 'spike', 'interdi', 'export ban', 'import ban',
  'suspend', 'rupture', 'crise', 'crisis', 'déficit', 'deficit', "appel d'offres", 'tender',
  'recherche fournisseur', 'seeking supplier', 'looking for supplier',
];

// 4) Une actualité n'est gardée que si elle parle aussi de commerce (évite les articles de cuisine ou de santé)
const motsCommerce = [
  'import', 'export', 'prix', 'price', 'marché', 'market', 'demande', 'demand', 'pénurie', 'shortage', 'cours',
  'filière', 'tonne', 'tons', 'fcfa', 'cfa', 'naira', 'achat', 'buyer', 'supplier', 'fournisseur', 'production',
  'récolte', 'harvest', 'trade', 'commerce', 'tarif', 'douane', 'customs', 'interdi', 'export ban', 'import ban',
  'stock', 'cargaison',
];

// 5) Recherches Google Actualités (même syntaxe que dans Google : OR, guillemets, parenthèses)
const recherchesActualites = [
  { q: 'Cameroun prix (maïs OR riz OR oignon OR "huile de palme" OR poisson)', langue: 'fr' },
  { q: 'Cameroun importation (riz OR poisson OR maïs OR "huile de palme" OR blé)', langue: 'fr' },
  { q: '(Gabon OR Congo OR Tchad OR "Guinée équatoriale") importation alimentaire', langue: 'fr' },
  { q: 'interdiction exportation (maïs OR riz OR oignon OR céréales OR bétail)', langue: 'fr' },
  { q: 'Cameroun exportation (cacao OR café OR poivre OR banane OR manioc)', langue: 'fr' },
  { q: 'ZLECAf agriculture', langue: 'fr' },
  { q: 'Nigeria food import (maize OR rice OR onion OR cassava OR poultry)', langue: 'en' },
  { q: 'Africa importers suppliers (cocoa OR cashew OR sesame OR ginger)', langue: 'en' },
  { q: 'Cameroon export (cocoa OR coffee OR pepper OR banana OR cassava)', langue: 'en' },
];
const joursActualites = 3; // n'aller chercher que les articles des 3 derniers jours

// 6) Pays et régions suivis pour les appels d'offres de la Banque mondiale (noms exacts en anglais)
const paysAppelsOffres = [
  'Cameroon', 'Chad', 'Central African Republic', 'Congo, Republic of', 'Gabon', 'Nigeria',
  'Congo, Democratic Republic of', 'Niger', "Cote d'Ivoire", 'Senegal', 'Ghana', 'Benin', 'Togo', 'Mali',
  'Burkina Faso', 'Guinea', 'Western and Central Africa', 'Central Africa', 'Africa',
];

return [
  { json: { email, googleSheetUrl, motsCles, motsAlerte, motsCommerce, recherchesActualites, joursActualites, paysAppelsOffres } },
];

// Met les appels d'offres de la Banque mondiale au format commun des signaux.
// On ne garde que ceux dont la date limite n'est pas dépassée.
const MOIS = { Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06', Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12' };
const enIso = (d) => {
  const m = /^(\d{2})-(\w{3})-(\d{4})$/.exec(d || '');
  return m ? `${m[3]}-${MOIS[m[2]] || '01'}-${m[1]}` : '';
};
const aujourdhui = $now.toISODate();

const sorties = [];
for (const n of $input.first().json.procnotices || []) {
  const dateLimite = (n.submission_deadline_date || '').slice(0, 10);
  if (dateLimite && dateLimite < aujourdhui) continue;
  sorties.push({
    json: {
      id: `bm:${n.id}`,
      type: "Appel d'offres",
      source: 'Banque mondiale',
      date: enIso(n.noticedate),
      pays: n.project_ctry_name || '',
      titre: n.bid_description || n.project_name || '',
      lien: `https://projects.worldbank.org/en/projects-operations/procurement-detail/${n.id}`,
      acheteur: n.contact_organization || '',
      contact: [n.contact_name, n.contact_email, n.contact_phone_no].filter(Boolean).join(' · '),
      date_limite: dateLimite,
      texte: n.bid_description || '',
    },
  });
}
return sorties;

// Une adresse de flux RSS Google Actualités par recherche
const p = $input.first().json;
const LANGUES = { fr: 'hl=fr&gl=FR&ceid=FR:fr', en: 'hl=en-US&gl=US&ceid=US:en' };
return p.recherchesActualites.map((r) => ({
  json: {
    url: `https://news.google.com/rss/search?q=${encodeURIComponent(`${r.q} when:${p.joursActualites}d`)}&${LANGUES[r.langue] || LANGUES.fr}`,
  },
}));

// Met les articles au format commun des signaux
const sorties = [];
for (const item of $input.all()) {
  const a = item.json;
  if (!a.link || !a.title) continue;
  sorties.push({
    json: {
      id: `actu:${a.guid || a.link}`,
      type: 'Actualité',
      source: 'Google Actualités',
      date: (a.isoDate || '').slice(0, 10),
      pays: '',
      titre: a.title,
      lien: a.link,
      acheteur: '',
      contact: '',
      date_limite: '',
      texte: `${a.title} ${a.contentSnippet || ''}`,
    },
  });
}
return sorties;

// Garde les signaux qui parlent de tes produits (et, pour les actualités, de commerce), repère les pays cités,
// marque les urgents et ne laisse passer que ceux jamais vus lors des passages précédents.
const p = $('Paramètres').first().json;
const aujourdhui = $now.toISODate();

const echapper = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const debutDeMot = (mot) => new RegExp(`(^|[^\\p{L}])${echapper(mot)}`, 'iu');
const motEntier = (mot) => new RegExp(`(^|[^\\p{L}])${echapper(mot)}($|[^\\p{L}])`, 'iu');
const reglesProduits = p.motsCles.map((m) => [m, debutDeMot(m)]);
const reglesAlerte = p.motsAlerte.map((m) => [m, debutDeMot(m)]);
const reglesCommerce = p.motsCommerce.map((m) => debutDeMot(m));

const PAYS = [
  ['Cameroun', ['cameroun', 'cameroon']], ['Nigeria', ['nigeria']], ['Gabon', ['gabon']],
  ['Congo', ['congo', 'rdc', 'drc']], ['Tchad', ['tchad', 'chad']], ['Centrafrique', ['centrafrique', 'centrafricaine', 'central african']],
  ['Guinée équatoriale', ['guinée équatoriale', 'equatorial guinea']], ["Côte d'Ivoire", ["côte d'ivoire", "cote d'ivoire", 'ivory coast']],
  ['Ghana', ['ghana']], ['Sénégal', ['sénégal', 'senegal']], ['Bénin', ['bénin', 'benin']], ['Togo', ['togo']],
  ['Niger', ['niger']], ['Mali', ['mali']], ['Burkina Faso', ['burkina']], ['Guinée', ['guinée', 'guinea']],
  ['Maroc', ['maroc', 'morocco']], ['Algérie', ['algérie', 'algeria']], ['Tunisie', ['tunisie', 'tunisia']],
  ['Égypte', ['égypte', 'egypt']], ['Kenya', ['kenya']], ['Éthiopie', ['éthiopie', 'ethiopia']],
  ['Afrique du Sud', ['afrique du sud', 'south africa']], ['Angola', ['angola']], ['Tanzanie', ['tanzanie', 'tanzania']],
  ['France', ['france']], ['Belgique', ['belgique', 'belgium']], ['Pays-Bas', ['pays-bas', 'netherlands']],
  ['Allemagne', ['allemagne', 'germany']], ['Chine', ['chine', 'china']], ['Inde', ['inde', 'india']],
  ['Turquie', ['turquie', 'turkey', 'türkiye']], ['Émirats', ['émirats', 'emirates', 'uae', 'dubai', 'dubaï']],
  ['États-Unis', ['états-unis', 'united states', 'usa']],
].map(([nom, variantes]) => [nom, variantes.map(motEntier)]);

const memoire = $getWorkflowStaticData('global');
memoire.dejaVus ??= [];
const vus = new Set(memoire.dejaVus);

const sorties = [];
for (const item of $input.all()) {
  const s = item.json;
  if (!s.id || vus.has(s.id)) continue;
  const texte = s.texte || s.titre || '';
  const produits = reglesProduits.filter(([, r]) => r.test(texte)).map(([m]) => m);
  if (!produits.length) continue;
  if (s.type === 'Actualité' && !reglesCommerce.some((r) => r.test(texte))) continue;
  vus.add(s.id);
  memoire.dejaVus.push(s.id);

  const alertes = reglesAlerte.filter(([, r]) => r.test(texte)).map(([m]) => m);
  const paysCites = PAYS.filter(([, regles]) => regles.some((r) => r.test(texte))).map(([nom]) => nom);
  sorties.push({
    json: {
      date_detection: aujourdhui,
      priorite: s.type === "Appel d'offres" || alertes.length ? 'haute' : 'normale',
      type: s.type,
      source: s.source,
      pays: s.pays || paysCites.join(', '),
      produits: [...new Set(produits)].join(', '),
      titre: s.titre,
      lien: s.lien,
      acheteur: s.acheteur,
      contact: s.contact,
      date_limite: s.date_limite,
      date: s.date,
      statut: 'nouveau',
      notes: '',
      id: s.id,
    },
  });
}

// La mémoire garde les 5 000 derniers signaux vus
memoire.dejaVus = memoire.dejaVus.slice(-5000);

const ordre = (o) => (o.type === "Appel d'offres" ? 0 : 1) + (o.priorite === 'haute' ? 0 : 2);
sorties.sort((a, b) => ordre(a.json) - ordre(b.json) || String(b.json.date).localeCompare(String(a.json.date)));
return sorties;

// Met en forme l'alerte du jour (les 40 premiers signaux ; tout est dans la Google Sheet)
const p = $('Paramètres').first().json;
const signaux = $input.all().map((i) => i.json);
const ao = signaux.filter((s) => s.type === "Appel d'offres");
const actus = signaux.filter((s) => s.type !== "Appel d'offres");
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const ligne = (s) => `
  <li style="margin:0 0 10px">
    ${s.priorite === 'haute' ? '<b style="color:#b03434">●</b> ' : ''}<a href="${esc(s.lien)}">${esc(s.titre)}</a><br>
    <span style="color:#5a6a67;font-size:13px">${[s.pays, s.produits, s.date_limite && 'date limite ' + s.date_limite, s.acheteur, s.contact]
      .filter(Boolean)
      .map(esc)
      .join(' · ')}</span>
  </li>`;

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;color:#13201e;max-width:760px">
  <h2 style="margin:0 0 4px">Veille Afrique : ${signaux.length} nouveaux signaux</h2>
  <p style="margin:0 0 16px;color:#5a6a67">Tout est rangé dans <a href="${esc(p.googleSheetUrl)}">ta Google Sheet</a>, onglet « Signaux ». Mets à jour la colonne « statut » quand tu as contacté quelqu'un.</p>
  ${ao.length ? `<h3 style="margin:16px 0 8px">Appels d'offres (${ao.length})</h3><ul style="padding-left:18px">${ao.slice(0, 20).map(ligne).join('')}</ul>` : ''}
  ${actus.length ? `<h3 style="margin:16px 0 8px">Actualités (${actus.length})</h3><ul style="padding-left:18px">${actus.slice(0, 40 - Math.min(ao.length, 20)).map(ligne).join('')}</ul>` : ''}
  <p style="font-size:12px;color:#8a9895;margin-top:16px"><b style="color:#b03434">●</b> = urgent (appel d'offres, pénurie, interdiction, flambée des prix…).</p>
</div>`;

return [{ json: { sujet: `Veille Afrique : ${signaux.length} nouveaux signaux${ao.length ? ` dont ${ao.length} appel(s) d'offres` : ''}`, html } }];
